//! Raw VA-API declarations.
//!
//! `va_api` is generated by bindgen from the libva 2.20 headers (MIT licence:
//! "Copyright (c) 2007-2009 Intel Corporation"), types and constants only. Its
//! layout assertions are compile-time, so a target whose ABI differs from the one
//! the bindings were generated on (Linux x86-64) fails to build. The entry points
//! are written out below and loaded at run time (`crate::loader`).

#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    missing_docs,
    unnecessary_transmutes,
    unused_imports,
    unsafe_op_in_unsafe_fn,
    clippy::all,
    clippy::undocumented_unsafe_blocks
)]

#[rustfmt::skip]
pub(crate) mod va_api;

pub(crate) use va_api::*;

use core::ffi::{c_char, c_int, c_uint, c_void};

